#include "defines.hpp"

// include benchmark-specific definitions (problem sizes etc.)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto t_vec = noarr::vector<'t'>();
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// 2D fields: i x j, with 'j' as the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
} tuning;


// Array initialization (translated from C init_array)
void init_array(int tmax, int nx, int ny, auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	(void)tmax;
	(void)nx;
	(void)ny;

	// _fict_[i] = i
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = static_cast<num_t>(t);
	});

	// ex[i][j], ey[i][j], hz[i][j]
	std::size_t nx_len = ex | get_length<'i'>();
	std::size_t ny_len = ex | get_length<'j'>();

	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = static_cast<num_t>(i * (j + 1)) / static_cast<num_t>(nx_len);
		ey[state] = static_cast<num_t>(i * (j + 2)) / static_cast<num_t>(ny_len);
		hz[state] = static_cast<num_t>(i * (j + 3)) / static_cast<num_t>(nx_len);
	});
}


// Main computational kernel (translated from C kernel_fdtd_2d)
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(int tmax, int nx, int ny, auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	(void)tmax;
	(void)nx;
	(void)ny;

#pragma scop
	// Outer time loop: for (t = 0; t < TMAX; t++)
	traverser(fict).template for_dims<'t'>([=](auto trav_t) {
		auto t_state = trav_t.state(); // contains 't'

		// for (j = 0; j < NY; j++)
		//   ey[0][j] = _fict_[t];
		traverser(ey)
			.order(noarr::fix<'i'>(0))
			.for_each([=](auto state) {
				ey[state] = fict[t_state];
			});

		// for (i = 1; i < NX; i++)
		//   for (j = 0; j < NY; j++)
		//     ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
		traverser(ey, hz)
			.order(noarr::shift<'i'>(1))
			.template for_dims<'i'>([=](auto trav_i) {
				trav_i.for_each([=](auto state) {
					ey[state] = ey[state] - SCALAR_VAL(0.5) *
						(hz[state] - hz[state - noarr::idx<'i'>(1)]);
				});
			});

		// for (i = 0; i < NX; i++)
		//   for (j = 1; j < NY; j++)
		//     ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
		traverser(ex, hz)
			.order(noarr::shift<'j'>(1))
			.template for_dims<'i'>([=](auto trav_i) {
				trav_i.for_each([=](auto state) {
					ex[state] = ex[state] - SCALAR_VAL(0.5) *
						(hz[state] - hz[state - noarr::idx<'j'>(1)]);
				});
			});

		// for (i = 0; i < NX-1; i++)
		//   for (j = 0; j < NY-1; j++)
		//     hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j] +
		//                                  ey[i+1][j] - ey[i][j]);
		std::size_t nx_len = hz | get_length<'i'>();
		std::size_t ny_len = hz | get_length<'j'>();

		traverser(hz, ex, ey)
			.order(
				noarr::slice<'i'>(0, nx_len - 1) ^
				noarr::slice<'j'>(0, ny_len - 1)
			)
			.template for_dims<'i'>([=](auto trav_i) {
				trav_i.for_each([=](auto state) {
					hz[state] = hz[state] - SCALAR_VAL(0.7) *
						((ex[state + noarr::idx<'j'>(1)] - ex[state]) +
						 (ey[state + noarr::idx<'i'>(1)] - ey[state]));
				});
			});
	});
#pragma endscop
}


// Printing (similar role as PolyBench print_array / DCE)
void print_array(auto ex, auto ey, auto hz) {
	using namespace noarr;

	std::cerr << "ex\n";
	noarr::serialize_data(std::cerr, ex ^ noarr::hoist<'i'>());

	std::cerr << "\ney\n";
	noarr::serialize_data(std::cerr, ey ^ noarr::hoist<'i'>());

	std::cerr << "\nhz\n";
	noarr::serialize_data(std::cerr, hz ^ noarr::hoist<'i'>());
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Common length settings
	auto set_lengths =
		noarr::set_length<'t'>(tmax) ^
		noarr::set_length<'i'>(nx) ^
		noarr::set_length<'j'>(ny);

	// Allocate bags:
	// ex, ey, hz: i x j
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_lengths);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_lengths);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_lengths);

	// _fict_: t
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ t_vec ^ set_lengths);

	// Initialize arrays
	init_array(static_cast<int>(tmax), static_cast<int>(nx), static_cast<int>(ny),
	           ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_fdtd_2d(static_cast<int>(tmax), static_cast<int>(nx), static_cast<int>(ny),
	               ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Optional data dump to stderr (to prevent dead-code elimination in benchmarks)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		print_array(ex.get_ref(), ey.get_ref(), hz.get_ref());
	}

	// Print timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);
} tuning;

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = (num_t)t;
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Initialize ex, ey, hz
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = ((num_t)i * (j + 1)) / (num_t)nx;
		ey[state] = ((num_t)i * (j + 2)) / (num_t)ny;
		hz[state] = ((num_t)i * (j + 3)) / (num_t)nx;
	});
}

// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// BLAS-like params in original:
	// Time-stepping FDTD on a 2D grid

#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();

		// ey[0][j] = _fict_[t] for all j
		trav_t
			.order(noarr::fix<'i'>(0))
			.for_each([=](auto state) {
				// state has i=0, all j; t in t_state
				ey[state] = fict[t_state];
			});

		// ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		// for i = 1..nx-1, j = 0..ny-1
		trav_t
			.order(noarr::slice<'i'>(1, nx - 1))
			.for_each([=](auto state) {
				// state: i in [1, nx-1], j in [0, ny-1]
				auto state_im1j = state - noarr::idx<'i'>(1);

				ey[state] = ey[state]
				            - SCALAR_VAL(0.5) * (hz[state] - hz[state_im1j]);
			});

		// ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		// for i = 0..nx-1, j = 1..ny-1
		trav_t
			.order(noarr::slice<'j'>(1, ny - 1))
			.for_each([=](auto state) {
				// state: i in [0, nx-1], j in [1, ny-1]
				auto state_ijm1 = state - noarr::idx<'j'>(1);

				ex[state] = ex[state]
				            - SCALAR_VAL(0.5) * (hz[state] - hz[state_ijm1]);
			});

		// hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                             + ey[i+1][j] - ey[i][j])
		// for i = 0..nx-2, j = 0..ny-2
		trav_t
			.order(noarr::slice<'i'>(0, nx - 1) ^ noarr::slice<'j'>(0, ny - 1))
			.for_each([=](auto state) {
				// state: i in [0, nx-2], j in [0, ny-2]
				auto state_i_jp1 = state + noarr::idx<'j'>(1);
				auto state_ip1_j = state + noarr::idx<'i'>(1);

				hz[state] = hz[state]
				            - SCALAR_VAL(0.7) * (
					            (ex[state_i_jp1] - ex[state]) +
					            (ey[state_ip1_j] - ey[state])
				            );
			});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Set lengths for spatial and temporal dimensions
	auto set_space = noarr::set_length<'i'>(nx) ^ noarr::set_length<'j'>(ny);
	auto set_time  = noarr::set_length<'t'>(tmax);

	// Allocate bags
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ tuning.fict_layout ^ set_time);

	// Initialize arrays
	init_array(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_fdtd_2d(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (if requested, mimicking PolyBench's conditional printing)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		// Hoist 'i' so each row is contiguous in the serialized output
		noarr::serialize_data(std::cerr, ex.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, ey.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, hz.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print elapsed time (seconds)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

