using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec); // 2D fields: i x j
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);          // 1D array: t
} tuning;

// initialization function
void init_array(int tmax, int nx, int ny, auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize _fict_: one-dimensional in 't'
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = static_cast<num_t>(t);
	});

	// Initialize ex, ey, hz: 2D in (i, j)
	auto nx_len = ex | get_length<'i'>();
	auto ny_len = ex | get_length<'j'>();

	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = static_cast<num_t>(i * (j + 1)) / static_cast<num_t>(nx_len);
		ey[state] = static_cast<num_t>(i * (j + 2)) / static_cast<num_t>(ny_len);
		hz[state] = static_cast<num_t>(i * (j + 3)) / static_cast<num_t>(nx_len);
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx_len = ex | get_length<'i'>();
	auto ny_len = ex | get_length<'j'>();

#pragma scop
	// outer time-stepping loop over 't'
	traverser(fict).for_each([=](auto t_state) {
		// Loop 1: for (j = 0; j < NY; j++) ey[0][j] = _fict_[t];
		traverser(ey)
			.order(noarr::fix<'i'>(0))
			.for_each([=](auto state) {
				ey[state] = fict[t_state];
			});

		// Loop 2: for (i = 1; i < NX; i++) for (j = 0; j < NY; j++)
		// ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
		traverser(ey, hz)
			.order(noarr::slice<'i'>(1, nx_len - 1))
			.for_each([=](auto state) {
				ey[state] = ey[state] - SCALAR_VAL(0.5) *
					(hz[state] - hz[state - noarr::idx<'i'>(1)]);
			});

		// Loop 3: for (i = 0; i < NX; i++) for (j = 1; j < NY; j++)
		// ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
		traverser(ex, hz)
			.order(noarr::slice<'j'>(1, ny_len - 1))
			.for_each([=](auto state) {
				ex[state] = ex[state] - SCALAR_VAL(0.5) *
					(hz[state] - hz[state - noarr::idx<'j'>(1)]);
			});

		// Loop 4: for (i = 0; i < NX-1; i++) for (j = 0; j < NY-1; j++)
		// hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j] + ey[i+1][j] - ey[i][j]);
		traverser(hz, ex, ey)
			.order(
				noarr::slice<'i'>(0, nx_len - 1) ^
				noarr::slice<'j'>(0, ny_len - 1))
			.for_each([=](auto state) {
				auto ex_right = ex[state + noarr::idx<'j'>(1)];
				auto ex_here  = ex[state];
				auto ey_down  = ey[state + noarr::idx<'i'>(1)];
				auto ey_here  = ey[state];

				hz[state] = hz[state] - SCALAR_VAL(0.7) *
					((ex_right - ex_here) + (ey_down - ey_here));
			});
	});
#pragma endscop
}

} // namespace

