	auto set_lengths =
		noarr::set_length<'t'>(tmax) ^
		noarr::set_length<'i'>(nx) ^
		noarr::set_length<'j'>(ny);

	// data bags
	auto ex   = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_lengths);
	auto ey   = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_lengths);
	auto hz   = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_lengths);
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ tuning.fict_layout ^ set_lengths);

	// initialize data
	init_array(static_cast<int>(tmax), static_cast<int>(nx), static_cast<int>(ny),
	           ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_fdtd_2d(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print live-out data (prevents dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		noarr::serialize_data(std::cerr, ex.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, ey.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, hz.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
