#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto t_vec = noarr::vector<'t'>();
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// ex, ey, hz: i x j
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// lengths
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// _fict_[t] = t
	traverser(fict).for_each([=](auto st) {
		auto t = get_index<'t'>(st);
		fict[st] = static_cast<num_t>(t);
	});

	// ex[i][j], ey[i][j], hz[i][j]
	traverser(ex, ey, hz).for_each([=](auto s) {
		auto [i, j] = get_indices<'i', 'j'>(s);

		ex[s] = (static_cast<num_t>(i) * static_cast<num_t>(j + 1)) /
		        static_cast<num_t>(nx);
		ey[s] = (static_cast<num_t>(i) * static_cast<num_t>(j + 2)) /
		        static_cast<num_t>(ny);
		hz[s] = (static_cast<num_t>(i) * static_cast<num_t>(j + 3)) /
		        static_cast<num_t>(nx);
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	const num_t c05 = SCALAR_VAL(0.5);
	const num_t c07 = SCALAR_VAL(0.7);

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	std::size_t nx_last = nx - 1;
	std::size_t ny_last = ny - 1;

	#pragma scop
	// time-stepping loop over t
	traverser(ex, ey, hz, fict).template for_dims<'t'>([=](auto trav_t) {
		// ey[0][j] = _fict_[t]
		trav_t.template for_dims<'j'>([=](auto trav_j) {
			auto sj = trav_j.state();
			auto j = get_index<'j'>(sj);

			// fict uses only 't', extra 'j' in state is ignored
			ey[noarr::idx<'i', 'j'>(0, j)] = fict[sj];
		});

		// for (i = 1; i < nx; i++)
		//   for (j = 0; j < ny; j++)
		//     ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
		trav_t.template for_dims<'i'>([=](auto trav_i) {
			auto si = trav_i.state();
			auto i = get_index<'i'>(si);

			if (i == 0)
				return; // skip i == 0

			trav_i.for_each([=](auto s) {
				// s has 't', 'i', 'j'
				auto s_prev_i = s - noarr::idx<'i'>(1);

				ey[s] = ey[s] - c05 * (hz[s] - hz[s_prev_i]);
			});
		});

		// for (i = 0; i < nx; i++)
		//   for (j = 1; j < ny; j++)
		//     ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
		trav_t.template for_dims<'i'>([=](auto trav_i) {
			trav_i.for_each([=](auto s) {
				auto j = get_index<'j'>(s);
				if (j == 0)
					return; // skip j == 0

				auto s_prev_j = s - noarr::idx<'j'>(1);

				ex[s] = ex[s] - c05 * (hz[s] - hz[s_prev_j]);
			});
		});

		// for (i = 0; i < nx - 1; i++)
		//   for (j = 0; j < ny - 1; j++)
		//     hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j] +
		//                        ey[i+1][j] - ey[i][j]);
		trav_t.for_each([=](auto s) {
			auto i = get_index<'i'>(s);
			auto j = get_index<'j'>(s);

			if (i >= nx_last || j >= ny_last)
				return; // skip boundary cells

			auto s_right = s + noarr::idx<'j'>(1); // (i, j+1)
			auto s_down  = s + noarr::idx<'i'>(1); // (i+1, j)

			hz[s] = hz[s] - c07 * ((ex[s_right] - ex[s]) +
			                       (ey[s_down]  - ey[s]));
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t tmax = TMAX;
	std::size_t nx   = NX;
	std::size_t ny   = NY;

	// set lengths
	auto space_lengths = noarr::set_length<'i'>(nx) ^
	                     noarr::set_length<'j'>(ny);
	auto time_lengths  = noarr::set_length<'t'>(tmax);

	// fields
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ space_lengths);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ space_lengths);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ space_lengths);

	// fictitious boundary array
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ t_vec ^ time_lengths);

	// initialize data
	init_array(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_fdtd_2d(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to avoid dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		noarr::serialize_data(std::cerr, ex.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, ey.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, hz.get_ref() ^ noarr::hoist<'i'>());
	}

