#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// common PolyBench / Noarr definitions
#include "defines.hpp"

// benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto t_vec = noarr::vector<'t'>();
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// lengths taken from the structures
	const std::size_t tmax = fict | get_length<'t'>();
	const std::size_t nx   = ex   | get_length<'i'>();
	const std::size_t ny   = ex   | get_length<'j'>();

	// _fict_[t] = (DATA_TYPE) t;
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = static_cast<num_t>(t);
	});

	// ex[i][j] = (i*(j+1)) / nx;
	// ey[i][j] = (i*(j+2)) / ny;
	// hz[i][j] = (i*(j+3)) / nx;
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = static_cast<num_t>(i * (j + 1)) / static_cast<num_t>(nx);
		ey[state] = static_cast<num_t>(i * (j + 2)) / static_cast<num_t>(ny);
		hz[state] = static_cast<num_t>(i * (j + 3)) / static_cast<num_t>(nx);
	});

	(void)tmax; // tmax is unused here, silence warnings
}

// -----------------------------------------------------------------------------
// Main computational kernel
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	const num_t c05 = SCALAR_VAL(0.5);
	const num_t c07 = SCALAR_VAL(0.7);

	// problem sizes from structures
	const std::size_t tmax = fict | get_length<'t'>();
	const std::size_t nx   = ex   | get_length<'i'>();
	const std::size_t ny   = ex   | get_length<'j'>();

	#pragma scop
	// for (t = 0; t < _PB_TMAX; t++)
	traverser(fict).for_each([&](auto t_state) {
		// current time index and boundary value
		const auto t_val = fict[t_state];

		// ---------------------------------------------------------------------
		// ey[0][j] = _fict_[t];
		// ---------------------------------------------------------------------
		auto ey_i0 = ey ^ noarr::fix<'i'>(0);

		traverser(ey_i0).for_each([=](auto s_j) {
			ey_i0[s_j] = t_val;
		});

		// ---------------------------------------------------------------------
		// for (i = 1; i < NX; i++)
		//   for (j = 0; j < NY; j++)
		//     ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
		// ---------------------------------------------------------------------
		traverser(ey, hz)
			.order(noarr::slice<'i'>(1, nx - 1)) // i in [1, nx-1]
			.for_each([=](auto s) {
				auto s_im1 = noarr::neighbor<'i'>(s, -1);
				ey[s] = ey[s] - c05 * (hz[s] - hz[s_im1]);
			});

		// ---------------------------------------------------------------------
		// for (i = 0; i < NX; i++)
		//   for (j = 1; j < NY; j++)
		//     ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
		// ---------------------------------------------------------------------
		traverser(ex, hz)
			.order(noarr::slice<'j'>(1, ny - 1)) // j in [1, ny-1]
			.for_each([=](auto s) {
				auto s_jm1 = noarr::neighbor<'j'>(s, -1);
				ex[s] = ex[s] - c05 * (hz[s] - hz[s_jm1]);
			});

		// ---------------------------------------------------------------------
		// for (i = 0; i < NX-1; i++)
		//   for (j = 0; j < NY-1; j++)
		//     hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                                  + ey[i+1][j] - ey[i][j]);
		// ---------------------------------------------------------------------
		traverser(hz, ex, ey)
			.order(noarr::slice<'i'>(0, nx - 1) ^ noarr::slice<'j'>(0, ny - 1))
			.for_each([=](auto s) {
				auto s_jp1 = noarr::neighbor<'j'>(s, +1);
				auto s_ip1 = noarr::neighbor<'i'>(s, +1);

				hz[s] = hz[s] - c07 * (
					(ex[s_jp1] - ex[s]) +
					(ey[s_ip1] - ey[s])
				);
			});
	});
	#pragma endscop

	(void)tmax; // silence unused warning (mirrors original semantics)
}

} // namespace

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t tmax = TMAX;
	std::size_t nx   = NX;
	std::size_t ny   = NY;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'t'>(tmax) ^
		noarr::set_length<'i'>(nx) ^
		noarr::set_length<'j'>(ny);

	// data structures:
	// ex, ey, hz: i x j (outer: i, inner: j)
	// _fict_: t
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ j_vec ^ i_vec ^ set_lengths);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ j_vec ^ i_vec ^ set_lengths);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ j_vec ^ i_vec ^ set_lengths);
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ t_vec ^ set_lengths);

	// initialize arrays
	init_array(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_fdtd_2d(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print data (to prevent dead-code elimination in benchmarking harness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		// hoist 'i' so we serialize row by row
		noarr::serialize_data(std::cerr, ex.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, ey.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, hz.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
